47	/// „überspringen"-Marker.
48	[[nodiscard]] constexpr std::string_view ycsb_token(cmd::WorkloadKind k) noexcept {
49	    switch (k) {
50	        case cmd::WorkloadKind::YCSB_A_Read50Write50: return "A";
51	        case cmd::WorkloadKind::YCSB_B_Read95Write5: return "B";
52	        case cmd::WorkloadKind::YCSB_C_ReadOnly: return "C";
53	        case cmd::WorkloadKind::YCSB_D_ReadLatest: return "D";
54	        case cmd::WorkloadKind::YCSB_E_Scan95: return "E";
55	        case cmd::WorkloadKind::YCSB_F_ReadModifyWrite: return "F";
56	        case cmd::WorkloadKind::InsertHeavy: return "IH"; // #31-Schritt-2: → profile_by_name make_insert_heavy (80/20)
57	        case cmd::WorkloadKind::LookupHeavy: return "LH"; // #31-Schritt-2: → profile_by_name make_lookup_heavy (95/5)
