41	/// Roh-Wall-Clock-ns je Op-Kind (GETRENNT, Doku 24 §2.1) + Wall-Clock-korrelierter Observer-POD am Ende.
42	struct WorkloadRunResult {
43	    std::string                     profile_name{};
44	    std::uint64_t                   op_count  = 0;
45	    std::int64_t                    total_ns  = 0;     ///< Summe der echt gemessenen Op-Wall-Clock-ns
46	    bool                            two_phase = false; ///< true = Rollback aktiv (sonst Kalt-Messung)
47	    std::vector<std::int64_t>       insert_ns{};
48	    std::vector<std::int64_t>       lookup_ns{};
49	    std::vector<std::int64_t>       erase_ns{};
50	    std::vector<std::int64_t>       clear_ns{};
51	    std::vector<std::int64_t>       scan_ns{};     ///< V5-#49-E: Range-Scan-Latenzen (leer wenn Tier nicht scanbar)
52	    std::vector<std::int64_t>       rmw_ns{};      ///< V5-#49-F: Read-Modify-Write-Latenzen
53	    std::uint64_t                   read_sink = 0; ///< Anti-Wegoptimierungs-Senke (gemessene Lookups + Scans)
54	    an::ComdareTierObserverSnapshot observer{};    ///< EIN konsolidierter Observer-POD am Lauf-Ende (korreliert, I1)
55	};
