57	// ─────────────────────────────────────────────────────────────────────────────
58	// run_workload_profile — generischer Host-Treiber EINES Lastprofils
59	// ─────────────────────────────────────────────────────────────────────────────
60	
61	/// Treibt die (vorgenerierte, reproduzierbare) Op-Sequenz `ops` über das Tier; jede gemessene Op via
62	/// Zwei-Phasen-Treiber (V5-I7) wenn `rollback != nullptr`. `ops` wird typischerweise via
63	/// `WorkloadGenerator(config).generate_all()` erzeugt — dieselbe Config+Seed ⇒ identische Sequenz über alle
64	/// Binaries (Reproduzierbarkeit-Pflicht). Latenzen werden je Op-Kind getrennt gesammelt.
65	[[nodiscard]] inline WorkloadRunResult run_workload_profile(
66	    an::IObservableTier& tier, an::IRollbackableTier* rollback, std::vector<WorkloadOp> const& ops,
67	    std::string_view    profile_name,
68	    an::IScannableTier* scan = nullptr) { // V5-#49-E: optional (alte DLLs → nullptr → Scan-Ops übersprungen)
69	    using clock = std::chrono::steady_clock;
70	    WorkloadRunResult r;
71	    r.profile_name = std::string(profile_name);
72	    r.op_count     = ops.size();
73	    r.two_phase    = (rollback != nullptr);
74	
75	    for (auto const& op : ops) {
76	        switch (op.kind) {
77	            case WorkloadOpKind::Insert: {
78	                auto const ns = ac::detail::two_phase_measure(rollback, [&]() -> std::int64_t {
79	                    auto const t0 = clock::now();
80	                    (void)tier.tier_insert(op.key, op.value);
81	                    auto const t1 = clock::now();
82	                    return ac::detail::abi_dur_ns(t0, t1);
83	                });
84	                r.insert_ns.push_back(ns);
85	                r.total_ns += ns;
86	                break;
87	            }
88	            case WorkloadOpKind::Lookup: {
89	                std::uint64_t measured_out = 0;
90	                bool          measured_hit = false;
91	                auto const    ns           = ac::detail::two_phase_measure(rollback, [&]() -> std::int64_t {
92	                    std::uint64_t out = 0;
93	                    auto const    t0  = clock::now();
94	                    bool const    hit = tier.tier_lookup(op.key, &out);
95	                    auto const    t1  = clock::now();
96	                    measured_hit      = hit;
97	                    measured_out      = out; // spiegelt nach two_phase_measure die MESS-Phase
98	                    return ac::detail::abi_dur_ns(t0, t1);
99	                });
100	                r.read_sink += measured_hit ? measured_out : 0u;
101	                r.lookup_ns.push_back(ns);
102	                r.total_ns += ns;
103	                break;
104	            }
105	            case WorkloadOpKind::Erase: {
106	                auto const ns = ac::detail::two_phase_measure(rollback, [&]() -> std::int64_t {
107	                    auto const t0 = clock::now();
108	                    (void)tier.tier_erase(op.key);
109	                    auto const t1 = clock::now();
110	                    return ac::detail::abi_dur_ns(t0, t1);
111	                });
112	                r.erase_ns.push_back(ns);
113	                r.total_ns += ns;
114	                break;
115	            }
116	            case WorkloadOpKind::Clear: {
117	                auto const ns = ac::detail::two_phase_measure(rollback, [&]() -> std::int64_t {
118	                    auto const t0 = clock::now();
119	                    tier.tier_clear();
120	                    auto const t1 = clock::now();
121	                    return ac::detail::abi_dur_ns(t0, t1);
122	                });
123	                r.clear_ns.push_back(ns);
124	                r.total_ns += ns;
125	                break;
126	            }
127	            case WorkloadOpKind::Scan: { // V5-#49-E: Range-Scan ab op.key über op.value (=scan_length) Records
128	                if (scan != nullptr) {
129	                    std::uint64_t scan_sum = 0;
130	                    auto const    ns       = ac::detail::two_phase_measure(rollback, [&]() -> std::int64_t {
131	                        std::uint64_t cs = 0;
132	                        auto const    t0 = clock::now();
133	                        (void)scan->tier_scan(op.key, op.value, &cs);
134	                        auto const t1 = clock::now();
135	                        scan_sum      = cs; // spiegelt nach two_phase_measure die MESS-Phase
136	                        return ac::detail::abi_dur_ns(t0, t1);
137	                    });
138	                    r.read_sink += scan_sum;
139	                    r.scan_ns.push_back(ns);
140	                    r.total_ns += ns;
141	                }
142	                // scan == nullptr → Tier nicht scanbar (alte DLL / Release): Op ehrlich übersprungen (kein Fake-Sample).
143	                break;
144	            }
145	            case WorkloadOpKind::ReadModifyWrite: { // V5-#49-F: lookup → modifizieren → upsert als EINE Op
146	                auto const ns = ac::detail::two_phase_measure(rollback, [&]() -> std::int64_t {
147	                    std::uint64_t       cur      = 0;
148	                    auto const          t0       = clock::now();
149	                    bool const          hit      = tier.tier_lookup(op.key, &cur); // READ
150	                    std::uint64_t const modified = (hit ? cur : 0u) ^ op.value;    // MODIFY (deterministisch)
151	                    (void)tier.tier_insert(op.key, modified);                      // WRITE (ComposedSearch-Upsert)
152	                    auto const t1 = clock::now();
153	                    return ac::detail::abi_dur_ns(t0, t1);
154	                });
155	                r.rmw_ns.push_back(ns);
156	                r.total_ns += ns;
157	                break;
158	            }
159	        }
160	    }
161	
162	    tier.tier_observe(&r.observer); // EIN korrelierter Observer-POD am Lauf-Ende
163	    return r;
164	}
