176	/// Fährt alle Profile des Plans gegen ein Tier. Vor JEDEM Profil wird der Tier geleert (tier_clear), damit
177	/// die Profile unabhängig + reproduzierbar sind. Ein Ergebnis je Profil (in Plan-Reihenfolge).
178	///
179	/// **GATE-VERTRAG (V5, Aufrufer-Pflicht):** Der Aufrufer MUSS das Tier VOR dem Aufruf gegen die std::map-
180	/// Konformität geprüft haben (pruef_dock::run_conformance_gate, import → GATE → messen) — diese Funktion misst
181	/// nur Performance und prüft KEINE Funktionalität (vgl. IPruefDock::measure-Vertrag, pruef_dock.hpp).
182	[[nodiscard]] inline std::vector<WorkloadRunResult>
183	run_measurement_plan(an::IObservableTier& tier, an::IRollbackableTier* rollback, MeasurementPlan const& plan,
184	                     an::IScannableTier* scan = nullptr) { // V5-#49-E: Scan-fähiges Tier (für YCSB-E-Profile)
185	    std::vector<WorkloadRunResult> results;
186	    results.reserve(plan.profiles.size());
187	    // V5-Audit-Härtung: nur zwei-phasig, wenn der Rollback EMPIRISCH exakt ist (einmalige Probe je Binary).
188	    if (rollback != nullptr && !ac::detail::rollback_is_empirically_exact(tier, rollback)) rollback = nullptr;
189	    for (auto const& cfg : plan.profiles) {
190	        if (!cfg.is_valid()) continue; // ungültiges Profil überspringen (Robustheit)
191	        tier.tier_clear();             // frischer Start je Profil
192	        WorkloadGenerator gen{cfg};    // dieselbe Config+Seed ⇒ identische Sequenz je Binary
193	        auto const        ops = gen.generate_all();
194	        results.push_back(run_workload_profile(tier, rollback, ops, cfg.name, scan));
195	    }
196	    return results;
197	}
